1263	        store.set_last_snapshot("w", 2).unwrap();
1264	        assert_eq!(store.load_state("w").unwrap(), state);
1265	    }
1266	
1267	    #[test]
1268	    fn last_snapshot_alone_creates_default_state() {
1269	        let store = Store::in_memory().unwrap();
1270	        store.set_last_snapshot("w", 2).unwrap();
1271	        let expected = WatchState {
1272	            last_snapshot: Some(2),
1273	            last_complete_snapshot: Some(2),
1274	            last_snapshot_complete: Some(true),
1275	            ..WatchState::default()
1276	        };
1277	        assert_eq!(store.load_state("w").unwrap(), expected);
1278	    }
1279	
1280	    #[test]
1281	    fn last_snapshot_never_moves_backwards() {
1282	        let store = Store::in_memory().unwrap();
1283	        // snapshot が 100 に収集を始め、その間に check が 110 で保存し、最後に snapshot が完了する
1284	        store.set_last_snapshot("w", 110).unwrap();
1285	        store.set_last_snapshot("w", 100).unwrap();
1286	        assert_eq!(store.load_state("w").unwrap().last_snapshot, Some(110));
1287	        store.set_last_snapshot("w", 120).unwrap();
1288	        assert_eq!(store.load_state("w").unwrap().last_snapshot, Some(120));
1289	    }
1290	
1291	    /// 別プロセスの代わりに同じファイルを複数の接続で開くための DB。drop で片付ける
1292	    struct TempDb {
1293	        dir: std::path::PathBuf,
1294	    }
1295	
1296	    impl TempDb {
1297	        fn new(name: &str) -> Self {
1298	            let dir =
1299	                std::env::temp_dir().join(format!("kuda-store-{name}-{}", std::process::id()));
1300	            let _ = std::fs::remove_dir_all(&dir);
1301	            std::fs::create_dir_all(&dir).unwrap();
1302	            Self { dir }
1303	        }
