        assert_eq!(store.hist("w", "rtt", Some(("hour", 9))).unwrap(), [(5, 3)]);
        assert_eq!(store.v1_hist("w").unwrap(), None);
        // 2 回目以降は引き取るものがない
        store.resolve_v1_hist("w", Some("weekday_hour")).unwrap();
        assert!(
            store
                .hist("w", "rtt", Some(("weekday_hour", 9)))
                .unwrap()
                .is_empty()
        );
