    #[test]
    fn v1_file_database_is_migrated_on_open() {
        let db = TempDb::new("v1");
        {
            let conn = Connection::open(db.path()).unwrap();
            conn.execute_batch(&format!("{SCHEMA_V1} PRAGMA user_version = 1;"))
