//! 発火条件の式と、連続回数・クールダウンの判定。
//!
//! 式は `loss >= 0.5 || rtt_p50 > baseline.rtt_p95 * 2` のような形で、
//! 値が無い変数（データ不足のベースラインや、全滅時の RTT）を含む比較は
//! 「不明」になる。最終結果が不明なら発火しない。

use crate::config::{ProbeKind, Trigger};
use serde::Deserialize;
use std::collections::BTreeMap;

/// probe の種類ごとに、条件式で使える変数。
///
/// 式のパースでは検査しない。変数は probe の種類で決まり、パースの時点では
/// どの probe の式か分からないので、`Config::validate_watch` が照合する。
/// 網羅的に match しているのは、probe の種類を足したときに許可リストの決め忘れを防ぐため。
pub fn variables_for(kind: ProbeKind) -> &'static [&'static str] {
    match kind {
        ProbeKind::Tcp
        | ProbeKind::Icmp
        | ProbeKind::Dns
        | ProbeKind::Http
        | ProbeKind::Command => &[
            "loss",
            "rtt_p50",
            "rtt_p95",
            "rtt_max",
            "value",
            "baseline.rtt_p50",
            "baseline.rtt_p95",
            "baseline.loss_p50",
            "baseline.loss_p95",
            "baseline.value_p50",
            "baseline.value_p95",
        ],
        // baseline.* は無い。時間帯の統計ではなく、既知の集合と比べる
        ProbeKind::Process => &[
            "loss",
            "unknown",
            "unknown_user_writable",
            "masquerade",
            "missing",
            "process_count",
        ],
    }
}

pub type Variables = BTreeMap<String, f64>;

#[derive(Debug, Clone, Deserialize)]
#[serde(try_from = "String")]
pub struct Expr {
    source: String,
    root: Cond,
}

#[derive(Debug, Clone, PartialEq)]
enum Cond {
    Or(Box<Cond>, Box<Cond>),
    And(Box<Cond>, Box<Cond>),
    Not(Box<Cond>),
    Cmp(CmpOp, Num, Num),
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum CmpOp {
    Gt,
    Ge,
    Lt,
    Le,
    Eq,
    Ne,
}

#[derive(Debug, Clone, PartialEq)]
enum Num {
    Literal(f64),
    Var(String),
    Neg(Box<Num>),
    Arith(ArithOp, Box<Num>, Box<Num>),
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum ArithOp {
    Add,
    Sub,
    Mul,
    Div,
}

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Number(f64),
    Ident(String),
    Op(&'static str),
}

const OPERATORS: [&str; 15] = [
    "||", "&&", ">=", "<=", "==", "!=", ">", "<", "!", "+", "-", "*", "/", "(", ")",
];

fn tokenize(source: &str) -> Result<Vec<Token>, String> {
    let mut tokens = Vec::new();
    let mut rest = source.trim_start();
    while let Some(c) = rest.chars().next() {
        if let Some(op) = OPERATORS.iter().find(|op| rest.starts_with(**op)) {
            tokens.push(Token::Op(op));
            rest = &rest[op.len()..];
        } else if c.is_ascii_digit() {
            let end = rest
                .find(|c: char| !c.is_ascii_digit() && c != '.')
                .unwrap_or(rest.len());
            let number = rest[..end]
                .parse()
                .map_err(|_| format!("invalid number: {}", &rest[..end]))?;
            tokens.push(Token::Number(number));
            rest = &rest[end..];
        } else if c.is_ascii_alphabetic() || c == '_' {
            let end = rest
                .find(|c: char| !c.is_ascii_alphanumeric() && c != '_' && c != '.')
                .unwrap_or(rest.len());
            tokens.push(Token::Ident(rest[..end].to_string()));
            rest = &rest[end..];
        } else {
            return Err(format!("unexpected character: {c:?}"));
        }
        rest = rest.trim_start();
    }
    Ok(tokens)
}

struct Parser {
    tokens: Vec<Token>,
    pos: usize,
}

impl Parser {
    fn eat(&mut self, op: &str) -> bool {
        let matched = matches!(self.tokens.get(self.pos), Some(Token::Op(o)) if *o == op);
        if matched {
            self.pos += 1;
        }
        matched
    }

    fn or(&mut self) -> Result<Cond, String> {
        let mut left = self.and()?;
        while self.eat("||") {
            left = Cond::Or(Box::new(left), Box::new(self.and()?));
        }
        Ok(left)
    }

    fn and(&mut self) -> Result<Cond, String> {
        let mut left = self.unary()?;
        while self.eat("&&") {
            left = Cond::And(Box::new(left), Box::new(self.unary()?));
        }
        Ok(left)
    }

    fn unary(&mut self) -> Result<Cond, String> {
        if self.eat("!") {
            return Ok(Cond::Not(Box::new(self.unary()?)));
        }
        // "(" は論理式の括弧か算術の括弧か読むまで分からないので、比較を先に試す
        let start = self.pos;
        match self.comparison() {
            Ok(cond) => Ok(cond),
            Err(error) => {
                self.pos = start;
                if !self.eat("(") {
                    return Err(error);
                }
                let inner = self.or()?;
                if !self.eat(")") {
                    return Err("expected ')'".to_string());
                }
                Ok(inner)
            }
        }
    }

    fn comparison(&mut self) -> Result<Cond, String> {
        let left = self.sum()?;
        let ops = [
            (">=", CmpOp::Ge),
            ("<=", CmpOp::Le),
            ("==", CmpOp::Eq),
            ("!=", CmpOp::Ne),
            (">", CmpOp::Gt),
            ("<", CmpOp::Lt),
        ];
        for (text, op) in ops {
            if self.eat(text) {
                return Ok(Cond::Cmp(op, left, self.sum()?));
            }
        }
        Err("expected a comparison such as `loss >= 0.5`".to_string())
    }

    fn sum(&mut self) -> Result<Num, String> {
        let mut left = self.product()?;
        loop {
            let op = if self.eat("+") {
                ArithOp::Add
            } else if self.eat("-") {
                ArithOp::Sub
            } else {
                return Ok(left);
            };
            left = Num::Arith(op, Box::new(left), Box::new(self.product()?));
        }
    }

    fn product(&mut self) -> Result<Num, String> {
        let mut left = self.atom()?;
        loop {
            let op = if self.eat("*") {
                ArithOp::Mul
            } else if self.eat("/") {
                ArithOp::Div
            } else {
                return Ok(left);
            };
            left = Num::Arith(op, Box::new(left), Box::new(self.atom()?));
        }
    }

    fn atom(&mut self) -> Result<Num, String> {
        if self.eat("-") {
            return Ok(Num::Neg(Box::new(self.atom()?)));
        }
        if self.eat("(") {
            let inner = self.sum()?;
            if !self.eat(")") {
                return Err("expected ')'".to_string());
            }
            return Ok(inner);
        }
        let token = self.tokens.get(self.pos).cloned();
        self.pos += 1;
        match token {
            Some(Token::Number(n)) => Ok(Num::Literal(n)),
            Some(Token::Ident(name)) => Ok(Num::Var(name)),
            Some(Token::Op(op)) => Err(format!("unexpected {op:?}")),
            None => Err("unexpected end of expression".to_string()),
        }
    }
}

impl TryFrom<String> for Expr {
    type Error = String;

    fn try_from(source: String) -> Result<Self, String> {
        let tokens = tokenize(&source)?;
        let mut parser = Parser { tokens, pos: 0 };
        let root = parser.or()?;
        if parser.pos != parser.tokens.len() {
            return Err(format!(
                "unexpected trailing input in {source:?} at token {}",
                parser.pos + 1
            ));
        }
        Ok(Self { source, root })
    }
}

impl Expr {
    pub fn source(&self) -> &str {
        &self.source
    }

    /// 式の中で使っている変数名（出現順、重複なし）
    pub fn variables(&self) -> Vec<&str> {
        let mut names = Vec::new();
        self.root.collect_variables(&mut names);
        names
    }

    /// 不明（判定材料が足りない）場合は発火させない
    pub fn matches(&self, vars: &Variables) -> bool {
        self.root.eval(vars) == Some(true)
    }
}

impl Cond {
    fn collect_variables<'a>(&'a self, names: &mut Vec<&'a str>) {
        match self {
            Self::Or(a, b) | Self::And(a, b) => {
                a.collect_variables(names);
                b.collect_variables(names);
            }
            Self::Not(inner) => inner.collect_variables(names),
            Self::Cmp(_, a, b) => {
                a.collect_variables(names);
                b.collect_variables(names);
            }
        }
    }

    fn eval(&self, vars: &Variables) -> Option<bool> {
        match self {
            Self::Or(a, b) => match (a.eval(vars), b.eval(vars)) {
                (Some(true), _) | (_, Some(true)) => Some(true),
                (Some(false), Some(false)) => Some(false),
                _ => None,
            },
            Self::And(a, b) => match (a.eval(vars), b.eval(vars)) {
                (Some(false), _) | (_, Some(false)) => Some(false),
                (Some(true), Some(true)) => Some(true),
                _ => None,
            },
            Self::Not(inner) => inner.eval(vars).map(|value| !value),
            Self::Cmp(op, a, b) => {
                let (a, b) = (a.eval(vars)?, b.eval(vars)?);
                Some(match op {
                    CmpOp::Gt => a > b,
                    CmpOp::Ge => a >= b,
                    CmpOp::Lt => a < b,
                    CmpOp::Le => a <= b,
                    CmpOp::Eq => a == b,
                    CmpOp::Ne => a != b,
                })
            }
        }
    }
}

impl Num {
    fn collect_variables<'a>(&'a self, names: &mut Vec<&'a str>) {
        match self {
            Self::Literal(_) => {}
            Self::Var(name) => {
                if !names.contains(&name.as_str()) {
                    names.push(name);
                }
            }
            Self::Neg(inner) => inner.collect_variables(names),
            Self::Arith(_, a, b) => {
                a.collect_variables(names);
                b.collect_variables(names);
            }
        }
    }

    fn eval(&self, vars: &Variables) -> Option<f64> {
        match self {
            Self::Literal(value) => Some(*value),
            Self::Var(name) => vars.get(name).copied(),
            Self::Neg(inner) => inner.eval(vars).map(|value| -value),
            Self::Arith(op, a, b) => {
                let (a, b) = (a.eval(vars)?, b.eval(vars)?);
                match op {
                    ArithOp::Add => Some(a + b),
                    ArithOp::Sub => Some(a - b),
                    ArithOp::Mul => Some(a * b),
                    ArithOp::Div => (b != 0.0).then(|| a / b),
                }
            }
        }
    }
}

/// watch ごとに永続化する判定状態
#[derive(Debug, Clone, Default, PartialEq)]
pub struct TriggerState {
    /// 条件が連続で成立している回数
    pub streak: u32,
    /// 今回の異常の開始時刻
    pub since: Option<i64>,
    pub last_fired: Option<i64>,
    /// 発火済みで、まだ回復していない
    pub active: bool,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Outcome {
    Normal,
    /// 条件は成立しているが連続回数が足りない
    Pending,
    /// クールダウン中で発火を見送った
    Suppressed,
    Fired,
    Recovered,
}

/// 1 回分の判定結果を状態へ反映する。時刻は Unix 秒
pub fn advance(state: &mut TriggerState, matched: bool, trigger: &Trigger, now: i64) -> Outcome {
    if !matched {
        let outcome = if state.active {
            Outcome::Recovered
        } else {
            Outcome::Normal
        };
        state.streak = 0;
        state.since = None;
        state.active = false;
        return outcome;
    }

    state.streak += 1;
    state.since.get_or_insert(now);
    if state.streak < trigger.consecutive {
        return Outcome::Pending;
    }
    let cooldown = trigger.cooldown.as_secs() as i64;
    if state.last_fired.is_some_and(|fired| now - fired < cooldown) {
        return Outcome::Suppressed;
    }
    state.last_fired = Some(now);
    state.active = true;
    Outcome::Fired
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::time::Duration;

    fn expr(source: &str) -> Expr {
        Expr::try_from(source.to_string()).unwrap()
    }

    fn vars(pairs: &[(&str, f64)]) -> Variables {
        pairs.iter().map(|(k, v)| (k.to_string(), *v)).collect()
    }

    const EXAMPLE: &str = "loss >= 0.5 || rtt_p50 > baseline.rtt_p95 * 2";

    #[test]
    fn example_condition_fires_on_loss_without_baseline() {
