1	//! SQLite: メトリクス・集計・スナップショット・判定状態。
2	
3	use crate::probe::{ProbeRun, TargetResult};
4	use crate::trigger::TriggerState;
5	use anyhow::{Context, Result, bail};
6	use rusqlite::{Connection, OptionalExtension, Transaction, TransactionBehavior, params};
7	use serde_json::{Value, json};
8	use std::collections::HashMap;
9	use std::path::Path;
10	use std::time::Duration;
11	
12	/// `MIGRATIONS[i]` は版 i の DB を版 i + 1 へ上げる。新規 DB は版 0 から順に適用する。
13	/// 版を足すときは末尾に追加し、既存の要素は書き換えない
14	const MIGRATIONS: [&str; 4] = [
15	    SCHEMA_V1,
16	    HIST_BY_AGGREGATION,
17	    KNOWN_GOOD,
18	    PROCESS_IDENTITIES,
19	];
20	
21	/// 版 1 の分布に付ける `aggregate_by`。記録時の集計方式が分からない
22	const HIST_V1: &str = "v1";
23	/// 版 1 の分布のうち、現在の集計方式に合わず引き取れなかったもの。全体の統計にだけ使う
24	const HIST_UNKNOWN: &str = "unknown";
25	
26	/// 版 2: bucket の意味は集計方式で変わるので、分布を集計方式ごとに分ける
27	const HIST_BY_AGGREGATION: &str = "
28	    CREATE TABLE baseline_hist_v2 (
29	        watch TEXT NOT NULL,
30	        aggregate_by TEXT NOT NULL,
31	        series TEXT NOT NULL,
32	        bucket INTEGER NOT NULL,
33	        bin INTEGER NOT NULL,
34	        count INTEGER NOT NULL,
35	        PRIMARY KEY (watch, aggregate_by, series, bucket, bin)
36	    ) WITHOUT ROWID;
37	    INSERT INTO baseline_hist_v2 (watch, aggregate_by, series, bucket, bin, count)
38	        SELECT watch, 'v1', series, bucket, bin, count FROM baseline_hist;
39	    DROP TABLE baseline_hist;
40	    ALTER TABLE baseline_hist_v2 RENAME TO baseline_hist;
41	";
42	
43	/// 版 3: 取得履歴（snapshots）と比較基準を分ける。比較基準は collector ごとに
44	/// 最後に成功したデータを持ち、失敗した取得で置き換えない。
45	/// 既存の履歴からは collector ごとに最後の成功を拾って基準にする。全 collector が
46	/// 成功した最後の取得時刻は分からないので空にし、次の取得を再試行の間隔で行う
47	const KNOWN_GOOD: &str = "
48	    CREATE TABLE known_good (
49	        watch TEXT NOT NULL,
50	        collector TEXT NOT NULL,
51	        ts INTEGER NOT NULL,
52	        data TEXT NOT NULL,
53	        PRIMARY KEY (watch, collector)
54	    ) WITHOUT ROWID;
55	    -- 壊れた行で DB を開けなくならないよう、形の合わない行は読まずに飛ばす。
56	    -- SQLite は AND を左から評価するとは限らないので、CASE で順序を決める
57	    INSERT INTO known_good (watch, collector, ts, data)
58	        SELECT s.watch, c.key, MAX(s.ts), c.value -> '$.data'
59	        FROM snapshots AS s,
60	             json_each(
61	                 CASE WHEN NOT json_valid(s.data) THEN '{}'
62	                      WHEN json_type(s.data, '$.collectors') = 'object' THEN s.data
63	                      ELSE '{}' END,
64	                 '$.collectors'
65	             ) AS c
66	        WHERE CASE WHEN c.type = 'object'
67	                   THEN json_type(c.value, '$.ok') = 'true'
68	                        AND json_type(c.value, '$.data') IS NOT NULL
69	                   ELSE 0 END
70	        GROUP BY s.watch, c.key;
71	    ALTER TABLE watch_state ADD COLUMN last_complete_snapshot INTEGER;
72	    ALTER TABLE watch_state ADD COLUMN last_snapshot_complete INTEGER;
73	";
