661	    /// 今回見た識別キーを記録する。新しいものは `status` で登録し、
662	    /// 既にあるものは `last_seen` と `seen_count` だけを更新して status は変えない
663	    pub fn observe_identities(
664	        &mut self,
665	        watch: &str,
666	        ts: i64,
667	        seen: &[(String, IdentityStatus)],
668	    ) -> Result<()> {
669	        let tx = self.conn.transaction()?;
670	        for (identity, status) in seen {
671	            tx.execute(
672	                "INSERT INTO process_identities
673	                     (watch, identity, status, first_seen, last_seen, seen_count)
674	                 VALUES (?1, ?2, ?3, ?4, ?4, 1)
675	                 ON CONFLICT (watch, identity) DO UPDATE SET
676	                     last_seen = excluded.last_seen,
677	                     seen_count = seen_count + 1",
678	                params![watch, identity, status.as_str(), ts],
679	            )?;
680	        }
681	        tx.commit()?;
682	        Ok(())
683	    }
