1060	    fn v2_db(name: &str, snapshots: &[(i64, String)]) -> TempDb {
1061	        let db = TempDb::new(name);
1062	        let conn = Connection::open(db.path()).unwrap();
1063	        conn.execute_batch(&format!(
1064	            "{SCHEMA_V1} {HIST_BY_AGGREGATION} PRAGMA user_version = 2;"
1065	        ))
1066	        .unwrap();
