1	//! プロセスの識別と分類。
2	//!
3	//! 識別・フラグ判定・除外・glob は純関数で、環境変数や実行中の OS は関数の中で読まない。
4	//! 呼び出し側が [`Os`] と [`Roots`] を渡す。こうしておくと、Windows のパス規則のテストを
5	//! Linux 上でも走らせられる。ストアを使う分類は [`classify`]。
6	
7	use crate::config::Watch;
8	use crate::probe::ProcessInfo;
9	use crate::store::{IdentityStatus, Store};
10	use crate::trigger::Variables;
11	use anyhow::Result;
12	use std::collections::{BTreeMap, HashMap, HashSet};
13	
14	/// パス規則を切り替えるための OS。実行中の OS とは限らない（テストのため）
15	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
16	pub enum Os {
17	    Windows,
18	    Linux,
19	}
20	
21	impl Os {
22	    pub fn current() -> Os {
23	        if cfg!(windows) {
24	            Os::Windows
25	        } else {
26	            Os::Linux
27	        }
28	    }
29	
30	    fn separator(self) -> char {
31	        match self {
32	            Os::Windows => '\\',
33	            Os::Linux => '/',
34	        }
35	    }
36	}
37	
38	/// 正規化の結果
39	#[derive(Debug, Clone, PartialEq, Eq)]
40	pub struct Identity {
41	    /// 識別キー。パスが取れたら正規化したパス、取れなければ `name:<小文字名>`
42	    pub key: String,
43	    /// Linux で実行ファイルが削除済み（` (deleted)`）だった。事件の証拠に載せる
44	    pub deleted: bool,
45	}
46	
47	/// パスの正規化のうち、バージョン要素の置き換えを除いた部分。フラグ判定にはこちらを使う
48	/// （`C:\Users\1.2.3\...` のような置き換えで場所の判定が変わらないように）
49	fn normalize_basic(os: Os, path: &str) -> (String, bool) {
50	    match os {
51	        Os::Windows => {
52	            let path = path.strip_prefix(r"\\?\").unwrap_or(path);
53	            (path.replace('/', "\\").to_ascii_lowercase(), false)
54	        }
55	        Os::Linux => match path.strip_suffix(" (deleted)") {
56	            Some(rest) => (rest.to_string(), true),
57	            None => (path.to_string(), false),
58	        },
59	    }
60	}
61	
62	/// パスを識別キーに正規化する（§2.2 の 1〜3）
63	pub fn normalize_path(os: Os, path: &str) -> Identity {
64	    let (path, deleted) = normalize_basic(os, path);
65	    let sep = os.separator();
66	    let key = path
67	        .split(sep)
68	        .map(|element| {
69	            if is_version_element(element) {
70	                "*"
71	            } else {
72	                element
73	            }
74	        })
75	        .collect::<Vec<_>>()
76	        .join(&sep.to_string());
77	    Identity { key, deleted }
78	}
79	
80	/// `(v|app-)?数字(.数字)+` の後に、任意で `[-+_.]` と英数字・`.` の列が続く形か。
81	/// 更新のたびに変わるディレクトリ名やファイル名を 1 つの識別キーにまとめるために使う。
82	/// `python3` や `x64` のように `.` を含まない数字は、バージョンとみなさない
83	fn is_version_element(element: &str) -> bool {
84	    let lower = element.to_ascii_lowercase();
85	    let rest = lower
86	        .strip_prefix("app-")
87	        .or_else(|| lower.strip_prefix('v'))
88	        .unwrap_or(&lower);
89	    let bytes = rest.as_bytes();
90	
91	    let digits = |from: usize| {
92	        bytes[from..]
93	            .iter()
94	            .take_while(|b| b.is_ascii_digit())
95	            .count()
96	    };
97	    let first = digits(0);
98	    if first == 0 {
99	        return false;
100	    }
101	    let mut pos = first;
102	    let mut groups = 0;
103	    // `.` の後に数字が続く限りだけ食う。`1.2.3.exe` の `.exe` は後ろの列として扱う
104	    while pos < bytes.len() && bytes[pos] == b'.' {
105	        let n = digits(pos + 1);
106	        if n == 0 {
107	            break;
108	        }
109	        pos += 1 + n;
110	        groups += 1;
111	    }
112	    if groups == 0 {
113	        return false;
114	    }
115	    match bytes.get(pos) {
116	        None => true,
117	        Some(b'-' | b'+' | b'_' | b'.') => bytes[pos + 1..]
118	            .iter()
119	            .all(|b| b.is_ascii_alphanumeric() || *b == b'.'),
120	        Some(_) => false,
121	    }
122	}
123	
124	/// Linux のカーネルスレッドか。`/proc/<pid>/exe` が読めず、自身が kthreadd（PID 2）か
125	/// その子であるものを対象外にする。Windows では常に false
126	pub fn is_kernel_thread(os: Os, info: &ProcessInfo) -> bool {
127	    os == Os::Linux && info.path.is_none() && (info.pid == 2 || info.ppid == Some(2))
128	}
129	
130	/// プロセスの識別キーを求める。対象外（カーネルスレッド）は None
131	pub fn identify(os: Os, info: &ProcessInfo) -> Option<Identity> {
132	    if is_kernel_thread(os, info) {
133	        return None;
134	    }
135	    Some(match &info.path {
136	        Some(path) => normalize_path(os, path),
137	        None => Identity {
138	            key: format!("name:{}", info.name.to_lowercase()),
139	            deleted: false,
140	        },
141	    })
142	}
143	
144	/// フラグ判定に使う、解決済みの場所。環境変数はここへ渡す前に呼び出し側が読む
145	#[derive(Debug, Clone, PartialEq, Eq)]
146	pub struct Roots {
147	    os: Os,
148	    /// 正規化済み。末尾の区切りは無い
149	    user_writable: Vec<String>,
150	    /// 正規化済み（Windows の `%SystemRoot%`）
151	    system_root: String,
152	}
153	
154	impl Roots {
155	    /// 渡す値は正規化前でよい。空や根（`/`）は、全部が書き込み可能になってしまうので捨てる
156	    pub fn new(os: Os, user_writable: &[&str], system_root: Option<&str>) -> Roots {
157	        let trim = |p: &str| {
158	            let (p, _) = normalize_basic(os, p);
159	            p.trim_end_matches(os.separator()).to_string()
160	        };
161	        Roots {
162	            os,
163	            user_writable: user_writable
164	                .iter()
165	                .map(|p| trim(p))
166	                .filter(|p| !p.is_empty())
167	                .collect(),
168	            system_root: trim(system_root.unwrap_or(r"C:\Windows")),
169	        }
170	    }
171	
172	    /// 実行中の環境から組み立てる。環境変数を読むのはここだけ
173	    pub fn from_env() -> Roots {
174	        let os = Os::current();
175	        let var = |name: &str| std::env::var(name).unwrap_or_default();
176	        match os {
177	            Os::Windows => {
178	                let (profile, temp, tmp, root) = (
179	                    var("USERPROFILE"),
180	                    var("TEMP"),
181	                    var("TMP"),
182	                    var("SystemRoot"),
183	                );
184	                let root = (!root.is_empty()).then_some(root.as_str());
185	                Roots::new(os, &[&profile, &temp, &tmp, r"C:\Users\Public"], root)
186	            }
187	            Os::Linux => {
188	                let home = var("HOME");
189	                Roots::new(os, &[&home, "/tmp", "/var/tmp", "/dev/shm"], None)
190	            }
191	        }
192	    }
193	}
194	
195	/// `path` が `dir` と同じか、その配下にあるか。どちらも正規化済み
196	fn is_under(sep: char, path: &str, dir: &str) -> bool {
197	    path.strip_prefix(dir)
198	        .is_some_and(|rest| rest.is_empty() || rest.starts_with(sep))
199	}
200	
201	/// user_writable: 利用者が書き込める場所（ユーザーフォルダや一時領域）の配下にある実行ファイル
202	pub fn is_user_writable(roots: &Roots, path: &str) -> bool {
203	    let (path, _) = normalize_basic(roots.os, path);
204	    roots
205	        .user_writable
206	        .iter()
207	        .any(|dir| is_under(roots.os.separator(), &path, dir))
208	}
209	
210	/// Windows のシステムプロセスの名前
211	const SYSTEM_PROCESS_NAMES: &[&str] = &[
212	    "svchost.exe",
213	    "lsass.exe",
214	    "csrss.exe",
215	    "winlogon.exe",
216	    "wininit.exe",
217	    "services.exe",
218	    "smss.exe",
219	    "taskhostw.exe",
220	    "dllhost.exe",
221	    "conhost.exe",
222	    "rundll32.exe",
223	    "spoolsv.exe",
224	];
225	
226	/// masquerade: Windows のシステムプロセスの名前なのに、置き場所が違う。
227	/// パスが取れないもの（`path` が None）は判定しない。Linux では常に false
228	pub fn is_masquerade(roots: &Roots, name: &str, path: Option<&str>) -> bool {
229	    if roots.os != Os::Windows {
230	        return false;
231	    }
232	    let Some(path) = path else {
233	        return false;
234	    };
235	    let name = name.to_ascii_lowercase();
236	    let (path, _) = normalize_basic(roots.os, path);
237	    // 名前の表に無ければ対象外。explorer.exe だけは %SystemRoot% 直下が正しい置き場所
238	    let allowed: Vec<String> = if name == "explorer.exe" {
239	        vec![roots.system_root.clone()]
240	    } else if SYSTEM_PROCESS_NAMES.contains(&name.as_str()) {
241	        vec![
242	            format!(r"{}\system32", roots.system_root),
243	            format!(r"{}\syswow64", roots.system_root),
244	        ]
245	    } else {
246	        return false;
247	    };
248	    // 親ディレクトリの完全一致で見る。`system32\evil\svchost.exe` も不正にする
249	    let parent = path.rsplit_once('\\').map_or("", |(dir, _)| dir);
250	    !allowed.iter().any(|dir| dir == parent)
251	}
252	
253	/// 根のプロセスとその子孫を除いたプロセス一覧を返す。
254	///
255	/// `roots` は (PID, 起動時刻)。kuda 自身と実行中の調査プロセスを渡す。
256	/// 判断はすべて「除外しすぎない」側に倒す。除外は見えなくする操作なので、
257	/// 誤って除くより、kuda 自身が未知として見えるほうがまだ安全だから。
258	/// - 根は、一覧に同じ PID がいて起動時刻が一致するときだけ生きているとみなす（PID 再利用対策）
259	/// - 親子は、親の起動時刻 ≤ 子の起動時刻のときだけたどる。
260	///   どちらかの起動時刻が None のときは確かめられないので、たどらない
261	pub fn without_descendants<'a>(
262	    processes: &'a [ProcessInfo],
263	    roots: &[(u32, i64)],
264	) -> Vec<&'a ProcessInfo> {
265	    let by_pid: HashMap<u32, &ProcessInfo> = processes.iter().rev().map(|p| (p.pid, p)).collect();
266	    let mut children: HashMap<u32, Vec<&ProcessInfo>> = HashMap::new();
267	    for p in processes {
268	        if let Some(ppid) = p.ppid {
269	            children.entry(ppid).or_default().push(p);
270	        }
271	    }
272	
273	    let mut excluded: HashSet<u32> = HashSet::new();
274	    let mut queue: Vec<&ProcessInfo> = roots
275	        .iter()
276	        .filter_map(|&(pid, started)| {
277	            by_pid
278	                .get(&pid)
279	                .copied()
280	                .filter(|p| p.started == Some(started))
281	        })
282	        .collect();
283	    while let Some(parent) = queue.pop() {
284	        if !excluded.insert(parent.pid) {
285	            continue;
286	        }
287	        for &child in children.get(&parent.pid).into_iter().flatten() {
288	            match (parent.started, child.started) {
289	                (Some(ps), Some(cs)) if ps <= cs => queue.push(child),
290	                _ => {}
291	            }
292	        }
293	    }
294	    processes
295	        .iter()
296	        .filter(|p| !excluded.contains(&p.pid))
297	        .collect()
298	}
299	
300	/// `*`（区切りも跨ぐ）だけを扱う glob。大文字小文字は区別しない
301	/// （パターンもパスも小文字にそろえる。Linux のパスも同じ扱いにして規則を 1 つにする）
302	pub fn glob_match(pattern: &str, text: &str) -> bool {
303	    let pattern: Vec<char> = pattern.to_lowercase().chars().collect();
304	    let text: Vec<char> = text.to_lowercase().chars().collect();
305	    let (mut p, mut t) = (0, 0);
306	    // 直近の `*` の位置と、そのとき `*` に食わせていた text の終端
307	    let mut star: Option<(usize, usize)> = None;
308	    while t < text.len() {
309	        if p < pattern.len() && pattern[p] == '*' {
310	            star = Some((p, t));
311	            p += 1;
312	        } else if p < pattern.len() && pattern[p] == text[t] {
313	            p += 1;
314	            t += 1;
315	        } else if let Some((sp, st)) = star {
316	            p = sp + 1;
317	            t = st + 1;
318	            star = Some((sp, st + 1));
319	        } else {
320	            return false;
321	        }
322	    }
323	    pattern[p..].iter().all(|&c| c == '*')
324	}
325	
326	/// 自プロセスを `without_descendants` の根にするための (PID, 起動時刻)。
327	/// 起動時刻は列挙結果から自 PID を引いて得る。見つからなければ除外できない
328	pub fn own_root(processes: &[ProcessInfo]) -> Option<(u32, i64)> {
329	    let pid = std::process::id();
330	    processes
331	        .iter()
332	        .find(|p| p.pid == pid)
333	        .and_then(|p| p.started.map(|started| (pid, started)))
334	}
335	
336	/// 1 回の probe で報告対象（pending）になった識別キーと、その代表のプロセス
337	#[derive(Debug, Clone, PartialEq)]
338	pub struct PendingProcess {
339	    pub identity: Identity,
340	    /// 同じ識別キーのプロセスのうち、PID が最小のもの
341	    pub process: ProcessInfo,
342	    pub user_writable: bool,
343	    pub masquerade: bool,
344	}
345	
346	/// 分類の結果。ストアには `record` を呼ぶまで書かない
347	/// （異常と判定されたとき、学習しない形でやり直すため）
348	#[derive(Debug, Clone, PartialEq)]
349	pub struct Classification {
350	    /// unknown / unknown_user_writable / masquerade / missing / process_count
351	    pub metrics: Variables,
352	    /// 今 動いている pending。事件の証拠にする
353	    pub pending: Vec<PendingProcess>,
354	    /// 新しく known として登録する識別キーの数
355	    pub learned: usize,
356	    /// 今回見た識別キーと、新規のときに登録する status
357	    seen: Vec<(String, IdentityStatus)>,
358	}
359	
360	impl Classification {
361	    pub fn pending_identities(&self) -> Vec<String> {
362	        self.pending
363	            .iter()
364	            .map(|p| p.identity.key.clone())
365	            .collect()
366	    }
367	
368	    /// 今回見た識別キーを記録する。学習期間の起点もここで決まる
369	    pub fn record(&self, store: &mut Store, watch: &str, now: i64) -> Result<()> {
370	        store.start_learning(watch, now)?;
371	        store.observe_identities(watch, now, &self.seen)
372	    }
373	}
374	
375	/// 識別キーごとにまとめた、今 動いているプロセス
376	struct Observed<'a> {
377	    identity: Identity,
378	    process: &'a ProcessInfo,
379	    user_writable: bool,
380	    masquerade: bool,
381	}
382	
383	/// 動いているプロセスを既知の集合と照らして分類する。ストアは読むだけ。
384	///
385	/// `learn` が true で学習期間中なら、新しく見た識別キーを known にする（masquerade を除く）。
386	/// それ以外の新しい識別キーは pending にする。`excluded` は kuda 自身と調査プロセスの根
387	pub fn classify(
388	    store: &Store,
389	    watch: &Watch,
390	    processes: &[ProcessInfo],
391	    excluded: &[(u32, i64)],
392	    roots: &Roots,
393	    now: i64,
394	    learn: bool,
395	) -> Result<Classification> {
396	    let os = roots.os;
397	    let probe = &watch.probe;
398	    let mut observed: BTreeMap<String, Observed> = BTreeMap::new();
399	    for process in without_descendants(processes, excluded) {
400	        let Some(identity) = identify(os, process) else {
401	            continue;
402	        };
403	        if probe.ignore.iter().any(|g| glob_match(g, &identity.key)) {
404	            continue;
405	        }
406	        let path = process.path.as_deref();
407	        let masquerade = is_masquerade(roots, &process.name, path);
408	        let user_writable = path.is_some_and(|p| is_user_writable(roots, p));
409	        let entry = observed
410	            .entry(identity.key.clone())
411	            .or_insert_with(|| Observed {
412	                identity,
413	                process,
414	                user_writable,
415	                masquerade,
416	            });
417	        // 代表は PID が最小のもの。列挙の順序に結果を依存させない
418	        if process.pid < entry.process.pid {
419	            entry.process = process;
420	        }
421	        entry.masquerade |= masquerade;
422	    }
423	
424	    let started = store.learning_started(&watch.name)?.unwrap_or(now);
425	    let learning = watch
426	        .baseline
427	        .learn_for
428	        .is_some_and(|d| now < started.saturating_add(d.as_secs() as i64));
429	    let statuses = store.identity_statuses(&watch.name)?;
430	
431	    let mut seen = Vec::new();
432	    let mut pending = Vec::new();
433	    let mut learned = 0;
434	    for (key, o) in &observed {
435	        let status = match statuses.get(key) {
436	            Some(status) => *status,
437	            // 偽装は、学習期間中でも正常として覚えない
438	            None if learn && learning && !o.masquerade => {
439	                learned += 1;
440	                IdentityStatus::Known
441	            }
442	            None => IdentityStatus::Pending,
443	        };
444	        seen.push((key.clone(), status));
445	        if status == IdentityStatus::Pending {
446	            pending.push(PendingProcess {
447	                identity: o.identity.clone(),
448	                process: o.process.clone(),
449	                user_writable: o.user_writable,
450	                masquerade: o.masquerade,
451	            });
452	        }
453	    }
454	
455	    let count = |f: fn(&PendingProcess) -> bool| pending.iter().filter(|p| f(p)).count() as f64;
456	    let missing = probe
457	        .expected
458	        .iter()
459	        .filter(|g| !observed.keys().any(|key| glob_match(g, key)))
460	        .count();
461	    let mut metrics = Variables::new();
462	    metrics.insert("unknown".to_string(), pending.len() as f64);
463	    metrics.insert(
464	        "unknown_user_writable".to_string(),
465	        count(|p| p.user_writable),
466	    );
467	    metrics.insert("masquerade".to_string(), count(|p| p.masquerade));
468	    metrics.insert("missing".to_string(), missing as f64);
469	    metrics.insert("process_count".to_string(), observed.len() as f64);
470	    Ok(Classification {
471	        metrics,
472	        pending,
473	        learned,
474	        seen,
475	    })
476	}
477	
478	#[cfg(test)]
479	mod tests {
480	    use super::*;
481	
482	    fn norm(os: Os, path: &str) -> String {
483	        normalize_path(os, path).key
484	    }
485	
486	    fn info(pid: u32, ppid: Option<u32>, started: Option<i64>) -> ProcessInfo {
487	        ProcessInfo {
488	            pid,
489	            ppid,
490	            name: format!("p{pid}"),
491	            path: Some(format!("/bin/p{pid}")),
492	            user: None,
493	            started,
494	        }
495	    }
496	
497	    #[test]
498	    fn version_elements_are_replaced() {
499	        for element in [
500	            "1.2.3",
501	            "app-1.0.9",
502	            "v18.20.0",
503	            "2.1.0-beta.1",
504	            "130.0.6723.92",
505	            "APP-1.0.9",
506	            "V1.2",
507	        ] {
508	            assert!(is_version_element(element), "{element}");
509	        }
510	        assert_eq!(
511	            norm(
512	                Os::Windows,
513	                r"C:\Users\x\AppData\Local\app\app-1.0.9\app.exe"
514	            ),
515	            r"c:\users\x\appdata\local\app\*\app.exe"
516	        );
517	        assert_eq!(
518	            norm(Os::Linux, "/opt/node/v18.20.0/bin/node"),
519	            "/opt/node/*/bin/node"
520	        );

