45	pub fn format_time(ts: i64) -> String {
46	    Local.timestamp_opt(ts, 0).single().map_or_else(
47	        || ts.to_string(),
48	        |time| time.format("%Y-%m-%d %H:%M:%S %:z").to_string(),
49	    )
50	}
