73	pub fn create(incidents_dir: &Path, evidence: &Evidence, created: i64) -> Result<Incident> {
74	    let (id, dir) = create_unique_dir(&incidents_dir.join(evidence.watch), created)?;
75	    let incident = Incident {
76	        watch: evidence.watch.to_string(),
77	        id,
78	        created,
79	        since: evidence.since,
80	        dir,
81	    };
82	    let write = |name: &str, contents: String| {
83	        let path = incident.dir.join(name);
84	        std::fs::write(&path, contents).with_context(|| format!("failed to write {name}"))
85	    };
86	    write("summary.md", render_summary(evidence, created))?;
87	    write("diff.md", render_diff(evidence.last_good, evidence.current))?;
88	    write(
89	        "current.json",
90	        serde_json::to_string_pretty(evidence.current)?,
91	    )?;
92	    if let Some(data) = evidence.last_good {
93	        write("last_known_good.json", serde_json::to_string_pretty(data)?)?;
94	    }
95	    write("metrics.csv", render_metrics(evidence))?;
96	    write(META_FILE, serde_json::to_string_pretty(&incident)?)?;
97	    Ok(incident)
98	}
