139	        let paths = paths("garbage");
140	        let file = paths.data_dir.join(format!("{PREFIX}w"));
141	        std::fs::write(&file, "12").unwrap();
142	        assert!(running(&paths, &[me(1)]).is_empty());
143	        assert!(file.exists());
144	        std::fs::remove_dir_all(&paths.data_dir).unwrap();
145	    }
146	}
