1	//! 外部コマンドの起動。タイムアウトと、コンソール窓を出さないことをここで揃える。
2	
3	use anyhow::{Context, Result};
4	use std::io::{Read, Write};
5	use std::path::{Path, PathBuf};
6	use std::process::{Child, Command, Stdio};
7	use std::sync::{Arc, Mutex};
8	use std::thread::JoinHandle;
9	use std::time::{Duration, Instant};
10	
11	#[cfg(windows)]
12	const CREATE_NO_WINDOW: u32 = 0x0800_0000;
13	
14	#[derive(Debug)]
15	pub struct Output {
16	    /// タイムアウトで打ち切ったときは None
17	    pub code: Option<i32>,
18	    pub stdout: String,
19	    pub stderr: String,
20	    pub timed_out: bool,
21	}
22	
23	impl Output {
24	    pub fn success(&self) -> bool {
25	        self.code == Some(0)
26	    }
27	}
28	
29	/// 子プロセス用の `Command` を作る。Windows では窓が一瞬出ないようフラグを付ける
30	pub fn command(program: impl AsRef<std::ffi::OsStr>) -> Command {
31	    #[allow(unused_mut)]
32	    let mut command = Command::new(program);
33	    #[cfg(windows)]
34	    {
35	        use std::os::windows::process::CommandExt;
36	        command.creation_flags(CREATE_NO_WINDOW);
37	    }
38	    command
39	}
40	
41	fn capture(mut stream: impl Read + Send + 'static) -> (Arc<Mutex<Vec<u8>>>, JoinHandle<()>) {
42	    let buffer = Arc::new(Mutex::new(Vec::new()));
43	    let shared = Arc::clone(&buffer);
44	    let reader = std::thread::spawn(move || {
45	        let mut chunk = [0; 8192];
46	        while let Ok(n) = stream.read(&mut chunk) {
47	            if n == 0 {
48	                break;
49	            }
50	            if let Ok(mut buffer) = shared.lock() {
51	                buffer.extend_from_slice(&chunk[..n]);
52	            }
53	        }
54	    });
55	    (buffer, reader)
56	}
57	
58	fn lossy(buffer: &Mutex<Vec<u8>>) -> String {
59	    buffer
60	        .lock()
61	        .map(|bytes| String::from_utf8_lossy(&bytes).into_owned())
62	        .unwrap_or_default()
63	}
64	
65	/// 子プロセスとその子孫をまとめて止めるための入れ物。
66	/// Windows はジョブオブジェクト、Unix はプロセスグループで子孫を束ねる
67	#[cfg(windows)]
68	struct Tree {
69	    /// ジョブを作れなかったときは None で、直接の子だけを止める
70	    job: Option<windows::Win32::Foundation::HANDLE>,
71	}
72	
73	#[cfg(windows)]
74	impl Tree {
75	    fn prepare(_command: &mut Command) -> Self {
76	        Tree { job: None }
77	    }
78	
79	    /// ジョブに入れた後に起動された孫もジョブに属する。
80	    /// spawn から登録までの間に子が孫を起動すると取りこぼすが、その隙間はごく短い
81	    fn attach(&mut self, child: &mut Child) {
82	        use std::os::windows::io::AsRawHandle;
83	        use windows::Win32::Foundation::{CloseHandle, HANDLE};
84	        use windows::Win32::System::JobObjects::{
85	            AssignProcessToJobObject, CreateJobObjectW, JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE,
86	            JOBOBJECT_EXTENDED_LIMIT_INFORMATION, JobObjectExtendedLimitInformation,
87	            SetInformationJobObject,
88	        };
89	
90	        let result = unsafe {
91	            CreateJobObjectW(None, windows::core::PCWSTR::null()).and_then(|job| {
92	                // kuda が落ちてハンドルが閉じられたときも子孫ごと止まるようにする
93	                let mut info = JOBOBJECT_EXTENDED_LIMIT_INFORMATION::default();
94	                info.BasicLimitInformation.LimitFlags = JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
95	                let attached = SetInformationJobObject(
96	                    job,
97	                    JobObjectExtendedLimitInformation,
98	                    (&raw const info).cast(),
