29	/// 子プロセス用の `Command` を作る。Windows では窓が一瞬出ないようフラグを付ける
30	pub fn command(program: impl AsRef<std::ffi::OsStr>) -> Command {
31	    #[allow(unused_mut)]
32	    let mut command = Command::new(program);
33	    #[cfg(windows)]
34	    {
35	        use std::os::windows::process::CommandExt;
36	        command.creation_flags(CREATE_NO_WINDOW);
37	    }
38	    command
39	}
40	
41	fn capture(mut stream: impl Read + Send + 'static) -> (Arc<Mutex<Vec<u8>>>, JoinHandle<()>) {
42	    let buffer = Arc::new(Mutex::new(Vec::new()));
43	    let shared = Arc::clone(&buffer);
44	    let reader = std::thread::spawn(move || {
45	        let mut chunk = [0; 8192];
46	        while let Ok(n) = stream.read(&mut chunk) {
47	            if n == 0 {
48	                break;
49	            }
50	            if let Ok(mut buffer) = shared.lock() {
51	                buffer.extend_from_slice(&chunk[..n]);
52	            }
53	        }
54	    });
55	    (buffer, reader)
56	}
57	
58	fn lossy(buffer: &Mutex<Vec<u8>>) -> String {
59	    buffer
60	        .lock()
61	        .map(|bytes| String::from_utf8_lossy(&bytes).into_owned())
62	        .unwrap_or_default()
63	}
